('2000001','GOODS',1,1005001,'Volkswagen Golf 1.5 TSI 2019','One owner, full service history','<p>Golf 1.5 TSI Comfortline from 2019, 68,000 km, petrol, automatic. Serviced at the dealer, two sets of tyres on rims, no known faults.</p>','["https://picsum.photos/seed/announce-2000001-1/800/600", "https://picsum.photos/seed/announce-2000001-2/800/600"]','golf,vw,car',100,'København','2100',NULL,NULL,'PUBLISHED','2026-09-20 10:00:00','2027-03-20 10:00:00',NULL,'2026-09-28 00:00:00','2026-09-28 00:00:00',0),
('2000002','GOODS',1,1005001,'Toyota Yaris Hybrid 2021','Low mileage, winter tyres included','<p>Yaris 1.5 Hybrid Active, 31,000 km, one owner, non-smoker. Winter tyres on rims included.</p>','["https://picsum.photos/seed/announce-2000002-1/800/600", "https://picsum.photos/seed/announce-2000002-2/800/600"]','yaris,toyota,hybrid',181,'Aarhus','8000',NULL,NULL,'PUBLISHED','2026-09-20 10:00:00','2027-03-20 10:00:00',NULL,'2026-09-28 00:00:00','2026-09-28 00:00:00',0),
('2000003','GOODS',1,1005003,'Trek FX 3 hybrid bike, size M','Serviced this spring','<p>Trek FX 3 Disc, frame size M (54 cm), hydraulic disc brakes, new chain and cassette in April. Comes with rack and mudguards.</p>','["https://picsum.photos/seed/announce-2000003-1/800/600", "https://picsum.photos/seed/announce-2000003-2/800/600"]','bicycle,trek',151,'Odense','5000',NULL,NULL,'PUBLISHED','2026-09-20 10:00:00','2027-03-20 10:00:00',NULL,'2026-09-28 00:00:00','2026-09-28 00:00:00',0),
